import { OasVoid } from '@skmtc/core'
import type { OasOperation, OasOperationProjectionConstructorArgs } from '@skmtc/core'
import { toPathTemplate } from '@skmtc/lang-typescript'
import { ZodProjection } from '@skmtc/gen-zod'
import { ApiClientBase } from './base.ts'
import type { EnrichmentSchema } from './enrichments.ts'
import { toMethodName } from './naming.ts'

type ClientMethod = {
  name: string
  httpMethod: string
  path: string
  pathParams: string[]
  hasBody: boolean
  responseName: string
}

export class ApiClient extends ApiClientBase {
  clientMethods: ClientMethod[]

  constructor({ context, operation, settings }: OasOperationProjectionConstructorArgs<EnrichmentSchema>) {
    super({ context, operation, settings })

    this.clientMethods = []
  }

  append(operation: OasOperation) {
    const name = toMethodName(operation)

    const zodResponse = this.insertNormalizedModel(ZodProjection, {
      schema: operation.toSuccessResponse()?.resolve().toSchema() ?? OasVoid.empty(),
      fallbackName: `${name}Response`
    })

    this.clientMethods.push({
      name,
      httpMethod: operation.method.toUpperCase(),
      path: operation.path,
      pathParams: operation.toParams(['path']).map(param => param.name),
      hasBody: operation.method === 'post' || operation.method === 'put' || operation.method === 'patch',
      responseName: zodResponse.identifier.name
    })
  }

  override toString(): string {
    const methods = this.clientMethods
      .map(({ name, httpMethod, path, pathParams, hasBody, responseName }) => {
        const params = pathParams.map(param => `${param}: string`)

        if (hasBody) {
          params.push('body: unknown')
        }

        const requestInit = hasBody
          ? `{
      method: '${httpMethod}',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    }`
          : `{ method: '${httpMethod}' }`

        return `  async ${name}(${params.join(', ')}) {
    const res = await fetch(\`${toPathTemplate(path)}\`, ${requestInit})

    if (!res.ok) {
      throw new Error(await res.text())
    }

    return ${responseName}.parse(await res.json())
  }`
      })
      .join('\n\n')

    return `{
${methods}
}`
  }
}
===END===

DONE — `@exp/gen-api-client` is an accumulator-style operation generator modeled on `@skmtc/gen-express`: the entry (`src/mod.ts`) runs per operation and does the `findDefinition ?? insertOperation` get-or-create against a per-tag identity, where `base.ts` derives both the identifier (`OrdersClient`, `AddressesClient`, kind `class`) and the export path (`@/client/<Tag>Client.generated.ts`) from the operation's first tag, so each tag's class and file are created exactly once and every subsequent same-tag operation is routed to `append()` on the cached instance. `append()` stores only structured data — a deterministic method name from method + path segments (`getOrdersId`, `postOrders`), the uppercased HTTP method, path-parameter names from `operation.toParams(['path'])`, a body flag for mutating methods, and the response schema's constant name obtained by projecting the operation's success-response schema through `this.insertNormalizedModel(ZodProjection, …)` — which lets the engine materialize each zod model exactly once in its own file (shared `Order` refs dedupe through the cache) and auto-stitch the schema imports into the client files. All target syntax is composed only inside the prototype `toString()`, which renders the class body: one `async` method per operation with typed path parameters, a `toPathTemplate`-templated `fetch`, `JSON.stringify(body)` for POST bodies, and `<schema>.parse(await res.json())` for validated returns.

